import React, { useState, useEffect, useCallback } from 'react'
import { Table, Typography, Spin, Empty, Alert, Col, message, Row } from 'antd'
import LayoutContent from '../../../../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../../../../components/utility/layoutWrapper'
import { paymentHistoryColumns } from './constants'
import FinishPayment from './components/FinishPayment/finishPayment'
import CancelPayment from './components/CancelPayment/cancelPayment'
import { useCompanyPayments } from '../../../../state/Company/hooks/useCompany'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
// import { RowWithMargin } from '../../../../CommonComponents'
// import { ColTextAlignRight } from '../../../../CommonComponents/index.style'
// import PermissionCheckerV2 from '../../../../../../../components/permissionCheckerV2'
// import FileUploadOnGcs from '../../../../../../../components/FileUploadOnGcs/fileUploadOnGcs'
// import { useFileUploadStandalone } from '../../../../state/hooks'
// import ebUrls from '../../../../../../../request/urls/employeeBenefit'

const { Title } = Typography

const PaymentHistory = (props) => {
  const [{ companyPaymentsData }, request] = useCompanyPayments()
  const [{ COMPANY_PAYMENTS_LOADER }] = useLoaderContextValue()
  const [{ COMPANY_PAYMENTS_ERROR, companyPaymentsStatus }] = useErrorContextValue()
  const [finishModal, setFinsihModal] = useState({ visible: false, data: null })
  const [cancelPaymentModal, setCancelPaymentModal] = useState({ visible: false, data: null })
  // const { uploadRequest } = useFileUploadStandalone()
  const [{ UPLOAD_FILE_STANDALONE_ERROR, uploadFileStandaloneStatus }] = useErrorContextValue()
  const { resetError } = useResetError()

  // const handleUploadRequest = useCallback((file) => {
  //   uploadRequest({
  //     signedUrlBody: { identifier: 'claim', file_name: file.name, content_type: file.type },
  //     body: { file, url: ebUrls.uploadBulkStatusUpdateExcel },
  //     uploadUrl: ebUrls.uploadBulkStatusUpdateExcel,
  //     urlKey: 'url'
  //   })
  // }, [uploadRequest])

  useEffect(() => {
    if (!companyPaymentsStatus) {
      const query = {
        company_id: props.companyId
      }
      request({ query })
    }
  }, [companyPaymentsStatus, props.companyId, request])

  useEffect(() => {
    if (uploadFileStandaloneStatus === 'success') {
      message.success('File uploaded successfully.')
      resetError(['UPLOAD_FILE_STANDALONE_ERROR', 'uploadFileStandaloneStatus'])
    }
    if (UPLOAD_FILE_STANDALONE_ERROR) {
      resetError(['UPLOAD_FILE_STANDALONE_ERROR'])
    }
  }, [uploadFileStandaloneStatus, UPLOAD_FILE_STANDALONE_ERROR, resetError])
  const handleCancel = useCallback(() => {
    setFinsihModal(modalState => ({ ...modalState, visible: false }))
  }, [setFinsihModal])

  const handleCloseModalCancel = () => {
    setCancelPaymentModal(modalState => ({ ...modalState, visible: false }))
  }

  return (
    <LayoutContentWrapper>
      <LayoutContent>
        <Row>
          <Col span={4}>
            <Title level={4}>Payment History</Title>
          </Col>
          {/* <ColTextAlignRight>
            <PermissionCheckerV2 requiredPermission='ops.eb_upload_claim_file'>
              <FileUploadOnGcs
                uploadRequest={handleUploadRequest}
                buttonType='primary'
                label='Upload Employee List'
                isUploadSuccess={uploadFileStandaloneStatus === 'success'}
                isUploadFailed={UPLOAD_FILE_STANDALONE_ERROR}
                accept='.csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel'
              />
            </PermissionCheckerV2>
          </ColTextAlignRight> */}
        </Row>
        <Spin spinning={COMPANY_PAYMENTS_LOADER}>
          {COMPANY_PAYMENTS_ERROR && <Alert type='error' message={companyPaymentsStatus} banner />}
          {(companyPaymentsData)
            ? (
              <>
                <Table
                  bordered
                  dataSource={companyPaymentsData.data ? companyPaymentsData.data : []}
                  columns={paymentHistoryColumns(setFinsihModal, setCancelPaymentModal, props.companyId)}
                  rowKey={({ id }) => id}
                />
                {
                  finishModal.visible && (
                    <FinishPayment
                      data={finishModal.data}
                      onCancel={handleCancel}
                    />
                  )
                }
                {
                  cancelPaymentModal.visible && (
                    <CancelPayment
                      data={cancelPaymentModal.data}
                      onCancel={handleCloseModalCancel}
                      setFinsihModal={setFinsihModal}
                    />
                  )
                }
              </>
              )
            : <Empty />}
        </Spin>
      </LayoutContent>
    </LayoutContentWrapper>
  )
}

export default PaymentHistory
