/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect } from 'react'
import { Button, Col, Table, Typography, Spin, Empty, Icon, Alert } from 'antd'
import LayoutContent from '../../../../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../../../../components/utility/layoutWrapper'
import { packageColumns } from './constants'
import { useCompanyPackages } from '../../../../state/Company/hooks/useCompany'
import PermissionCheckerV2 from '../../../../../../../components/permissionCheckerV2'
import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { RowWithMargin } from '../../../../CommonComponents'

const { Title } = Typography

const Package = (props) => {
  const { history } = props
  const [{ companyPackageData }, request] = useCompanyPackages()
  const [{ COMPANY_PACKAGE_LOADER }] = useLoaderContextValue()
  const [{ COMPANY_PACKAGE_ERROR, companyPackageStatus }] = useErrorContextValue()

  useEffect(() => {
    request({ query: { company_id: props.companyId } })
  }, [])

  const addPackage = (params) => {
    history.push(`/employee-benefits/company-list/${props.companyId}/add-product`)
  }
  return (
    <LayoutContentWrapper>
      <LayoutContent>
        <RowWithMargin>
          <Col span={12}>
            <Title level={4}>Product</Title>
          </Col>
          <Col span={12} style={{ textAlign: 'right' }}>
            <PermissionCheckerV2
              requiredPermission='ops.eb_create_package'
            >
              <Button
                type='primary'
                onClick={addPackage}
              >
                <Icon type='plus-circle' /> Add Product
              </Button>
            </PermissionCheckerV2>
          </Col>
        </RowWithMargin>
        <Spin spinning={!!COMPANY_PACKAGE_LOADER}>
          {COMPANY_PACKAGE_ERROR && <Alert type='error' message={companyPackageStatus} banner />}
          {(companyPackageData && !COMPANY_PACKAGE_ERROR)
            ? (
              <>
                <Table
                  rowKey={({ _packageID }) => _packageID}
                  bordered
                  dataSource={companyPackageData.data}
                  pagination={{ pageSize: 5 }}
                  columns={packageColumns(history, props.companyId)}
                />
              </>
              )
            : <Empty />}
        </Spin>
      </LayoutContent>
    </LayoutContentWrapper>
  )
}

export default Package
