import React from 'react'
import { Icon, Tag } from 'antd'
import PermissionCheckerV2 from '../../../../../../../components/permissionCheckerV2'
import { formatIntlCurrency } from '../../../../../../../helpers/utility'
import { format } from 'date-fns'
import { FileLink } from './index.style'

export const paymentHistoryColumns = (setFinishModal, setCancelPaymentModal, companyId) => [
  {
    key: 1,
    title: 'Action',
    render: (rowData, row) => {
      switch (row.status) {
        case 'FINISHED':
          return <Icon type='check' style={{ color: 'rgb(50,215,75)' }} />
        case 'CANCELLED':
          return <Icon type='close' style={{ color: 'rgb(255, 69, 58)' }} />
        case 'FAILED':
          return <Icon type='stop' style={{ color: 'rgb(255, 69, 58)' }} />
        case 'CREATED':
          return <Icon type='hourglass' />
        case 'EXPIRED':
          return <Icon type='minus-circle-o' />
        default:
          return (
            <>
              <PermissionCheckerV2
                requiredPermission='ops.eb_finish_payment'
              >
                <Icon
                  type='check-circle'
                  twoToneColor='rgb(50,215,75)'
                  theme='twoTone'
                  style={{ cursor: 'pointer', margin: 4 }}
                  onClick={() => setFinishModal({ visible: true, data: rowData })}
                />
              </PermissionCheckerV2>

              <PermissionCheckerV2
                requiredPermission='ops.eb_cancel_payment'
              >
                <Icon
                  type='close-circle'
                  twoToneColor='rgb(255, 69, 58)'
                  theme='twoTone'
                  style={{ cursor: 'pointer', margin: 4 }}
                  onClick={() => setCancelPaymentModal({ visible: true, data: rowData })}
                />
              </PermissionCheckerV2>
            </>
          )
      }
    }
  },
  {
    key: 2,
    title: 'Id',
    dataIndex: 'id'
  },
  {
    key: 3,
    title: 'Package Id',
    dataIndex: 'packageID'
  },
  {
    key: 4,
    title: 'Amount',
    dataIndex: 'amount',
    render: amount => formatIntlCurrency(amount)
  },
  {
    key: 5,
    title: 'Txn Ref',
    dataIndex: 'txn_ref'
  },
  {
    key: 6,
    title: 'Txn Date',
    dataIndex: 'txn_date',
    render: transactionDate => transactionDate && format(transactionDate, 'DD-MM-YYYY')
  },
  {
    key: 7,
    title: 'Status',
    dataIndex: 'status'
  },
  {
    key: 8,
    title: 'Participant Count',
    dataIndex: 'filerows_status_count',
    render: (fileRowsStatus) => fileRowsStatus && <><Tag color='green'>Success - {fileRowsStatus?.success_rows}</Tag><Tag color='red'>Failed - {fileRowsStatus?.failed_rows}</Tag></>
  },
  {
    key: 9,
    title: 'Payment Type',
    dataIndex: 'file_id',
    render: fileId => fileId ? <><FileLink href={`/employee-benefits/company-list/${companyId}/file-uploads/${fileId}`}>File</FileLink></> : 'Manual'

  }
]
