import React from 'react'
import { Icon } from 'antd'
import PermissionCheckerV2 from '../../../../../../../components/permissionCheckerV2'
import { formatIntlCurrency } from '../../../../../../../helpers/utility'
export const packageColumns = (history, id) => [
  {
    key: 1,
    title: 'Action',
    render: (rowData) => (
      <PermissionCheckerV2
        requiredPermission='ops.eb_view_package_detail'
      >
        <Icon
          type='eye'
          twoToneColor='#0180c8'
          theme='twoTone'
          style={{ cursor: 'pointer' }}
          onClick={() => history.push(`/employee-benefits/company-list/${id}/product/${rowData._packageID}`)}
        />
      </PermissionCheckerV2>
    )
  },
  {
    key: 2,
    title: 'Product ID',
    dataIndex: '_packageID'
  },
  {
    key: 3,
    title: 'Provider',
    dataIndex: 'insurance_provider'
  },
  {
    key: 4,
    title: 'Benefits',
    render: (rowData) => {
      const data = rowData.benefitgroup__group_name.map((d, index) => (<li key={d + index}>{d}</li>))
      return data
    }
  },
  {
    key: 5,
    title: 'Total Premium (per year)',
    dataIndex: 'total_premium',
    render: totalPremium => formatIntlCurrency(totalPremium)
  }

]
