import React, { useEffect } from 'react'
import {
  Modal,
  Form,
  Col,
  Input,
  DatePicker,
  Alert,
  Spin
} from 'antd'
import { useUpdatePayment } from '../../../../../../state/Company/hooks/useCompany'
import moment from 'moment'
import { formatIntlCurrency } from '../../../../../../../../../helpers/utility'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useResetState } from '../../../../../../state/hooks'
import { RowWithMargin } from '../../../../../../CommonComponents'

const { Item } = Form

const FinishPayment = Form.create({ name: 'finish-payment' })(({ onCancel, form, ...props }) => {
  const { getFieldDecorator } = form
  const [, acceptPaymentRequest] = useUpdatePayment()
  const [{ ACCEPT_PAYMENT_ERROR, acceptPaymentStatus }] = useErrorContextValue()
  const [{ ACCEPT_PAYMENT_LOADER }] = useLoaderContextValue()
  const { resetState } = useResetState()
  const { resetError } = useResetError()
  const config = {
    rules: [{ type: 'string', required: true, message: 'Please select a transaction Id' }]
  }
  const dateConfig = {
    rules: [{ type: 'object', required: true, message: 'Please select a valid date' }]
  }
  const handleSubmit = () => {
    form.validateFields((err, fieldsValue) => {
      if (!err) {
        acceptPaymentRequest({
          body: {
            id: props.data.id,
            txn_ref: fieldsValue.txn_ref,
            txn_date: moment(fieldsValue.txn_date).format('YYYY-MM-DD')
          }
        })
      }
    })
  }
  useEffect(() => {
    if (acceptPaymentStatus === 'success') {
      resetState(['companyPaymentsData'])
      resetError(['COMPANY_PAYMENTS_ERROR', 'companyPaymentsStatus', 'acceptPaymentStatus', 'participantsInfoStatus'])
      onCancel()
    }
  }, [acceptPaymentStatus, onCancel, resetError, resetState])

  return (
    <Modal
      visible
      title='Finish Payment'
      onOk={handleSubmit}
      onCancel={onCancel}
    >
      <Form>
        <Spin spinning={!!ACCEPT_PAYMENT_LOADER}>
          {ACCEPT_PAYMENT_ERROR && <Alert type='error' message={acceptPaymentStatus} banner />}
          <RowWithMargin>
            <Col span={12}>ID</Col>
            <Col span={12}>{props.data ? props.data.id : '-'}</Col>
          </RowWithMargin>
          <RowWithMargin>
            <Col span={12}>Package ID</Col>
            <Col span={12}>{props.data ? props.data.packageID : '-'}</Col>
          </RowWithMargin>
          <RowWithMargin>
            <Col span={12}>Amount</Col>
            <Col span={12}>{props.data ? formatIntlCurrency(props.data.amount) : '-'}</Col>
          </RowWithMargin>
          <RowWithMargin>
            <Col span={12}>Txn Ref</Col>
            <Col span={12}>
              <Item hasFeedback>
                {getFieldDecorator('txn_ref', config)(
                  <Input type='text' />
                )}
              </Item>
            </Col>
          </RowWithMargin>
          <RowWithMargin>
            <Col span={12}>Txn Date</Col>
            <Col span={12}>
              <Item hasFeedback>
                {getFieldDecorator('txn_date', dateConfig)(
                  <DatePicker />
                )}
              </Item>
            </Col>
          </RowWithMargin>
        </Spin>
      </Form>
    </Modal>
  )
})

export default FinishPayment
