/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react'
import {
  Typography,
  Row,
  Col,
  Button,
  Spin,
  Empty,
  Icon,
  Tag,
  Alert,
  Upload,
  message
} from 'antd'
import LayoutContent from '../../../../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../../../../components/utility/layoutWrapper'
import { useParticipantInfo, useEmployeeDataUpload } from '../../../../state/Company/hooks/useCompany'
import ebUrls from '../../../../../../../request/urls/employeeBenefit'
import { useErrorContextValue, useGet, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useResetState } from '../../../../state/hooks'
import { RowWithMargin } from '../../../../CommonComponents'
import PermissionCheckerV2 from '../../../../../../../components/permissionCheckerV2'
import ExportExcel from '../../../../components/ExportExcel'
import { ComapnyApiConfig } from '../../apiConfig'

const { Title, Text } = Typography

const ParticipantInfo = (props) => {
  const { history } = props
  const [{ participantsInfoData }, request] = useParticipantInfo()
  const [{ PARTICIPANTS_INFO_LOADER, DOWNLOAD_PARTICIPANTS_LOADER }] = useLoaderContextValue()
  const [{
    PARTICIPANTS_INFO_ERROR,
    participantsInfoStatus,
    EMPLOYEE_DATA_UPLOAD_ERROR,
    employeeDataUploadStatus,
    DOWNLOAD_PARTICIPANTS_ERROR,
    downloadParticipantsStatus
  }] = useErrorContextValue()
  const [, downloadListRequest] = useGet(ComapnyApiConfig.downloadParticipants)
  const [, uploadRequest] = useEmployeeDataUpload()
  const [fileUploadState, setFileUploadState] = useState('')
  const { resetState } = useResetState()
  const { resetError } = useResetError()

  const customRequest = ({ file }, documentType) => {
    const { size } = file
    const isLt10KB = size / 1024 / 1024 < 0.001
    const isGt20MB = size / 1024 / 1024 > 20
    if (isLt10KB) {
      message.error('Image is to small, min 1kb')
      setFileUploadState(state => ({ ...state, [documentType]: 'done' }))
      return
    }
    if (isGt20MB) {
      message.error('Image is to big, max 20mb')
      setFileUploadState(state => ({ ...state, [documentType]: 'done' }))
      return
    }
    if (!isLt10KB && !isGt20MB) {
      const formData = new FormData()
      formData.append('file', file)
      formData.append('document_type', documentType)
      formData.append('company_id', props.companyId)
      setFileUploadState('')
      uploadRequest({
        params: {},
        // body: {file, documentType, companyId: props.companyId }
        body: { file, documentType, companyId: props.companyId },
        signedUrlBody: { file_name: file.name, identifier: 'employee_list', content_type: file.type },
        uploadBody: { document_type: documentType, company_id: props.companyId },
        uploadUrl: ebUrls.uploadEmployeeList,
        urlKey: 'url'
      })
    } else {
      message.error('Incorrect file type, please upload .jpeg/.jpg/.png')
    }
  }

  useEffect(() => {
    if (employeeDataUploadStatus === 'success') {
      setFileUploadState('done')
      message.success('File uploaded successfully')
      resetError(['employeeDataUploadStatus'])
    }
  }, [employeeDataUploadStatus])

  useEffect(() => {
    if (downloadParticipantsStatus === 'success') {
      message.success('File sent to email.')
    }
  }, [downloadParticipantsStatus])
  useEffect(() => {
    if (EMPLOYEE_DATA_UPLOAD_ERROR) {
      // TODO: handle error in file upload api
      setFileUploadState('done')
      message.error('Upload failed')
      resetError(['EMPLOYEE_DATA_UPLOAD_ERROR'])
    }
  }, [EMPLOYEE_DATA_UPLOAD_ERROR])

  useEffect(() => {
    return () => {
      // reset states here
      resetError([
        'PARTICIPANTS_INFO_ERROR',
        'EMPLOYEE_DATA_UPLOAD_ERROR',
        'employeeDataUploadStatus',
        'downloadParticipantsStatus'
      ])
      resetState([
        'participantsInfoStatus',
        'participantsInfoData',
        'employeeDataUploadData'
      ])
    }
  }, [])

  useEffect(() => {
    if (!participantsInfoStatus) {
      const query = {
        company_id: props.companyId
      }
      request({ query })
    }
  }, [participantsInfoStatus])

  const openParticipantsList = () => {
    history.push(`/employee-benefits/company-list/${props.companyId}/participants-list`)
  }

  const openEmployeeListPage = () => {
    history.push(`/employee-benefits/company-list/${props.companyId}/employee-list`)
  }

  return (
    <>
      <LayoutContentWrapper>
        <LayoutContent>
          <RowWithMargin type='flex' justify='space-between'>
            <Col span={4}>
              <Title level={4}>
                Participant Info
              </Title>
            </Col>
            <Col>
              <Row type='flex' justify='start' align='middle' gutter={32}>
                <Col>
                  <Row type='flex' align='middle'>
                    <Col><strong>Participant List:</strong></Col>
                    <Col>
                      <ExportExcel
                        url={ebUrls.downloadParticipantListTemplate}
                        buttonType='link'
                        buttonContent={<><Icon type='cloud-download' /> Template</>}
                      />
                    </Col>
                    <Col>
                      <PermissionCheckerV2 requiredPermission='ops.eb_upload_company_file'>
                        <Upload
                          customRequest={customRequest}
                          {...(fileUploadState === 'done' ? { fileList: [] } : null)}
                        >
                          <Button type='primary'><Icon type='cloud-upload' />Upload</Button>
                        </Upload>
                      </PermissionCheckerV2>
                    </Col>
                    <Col>
                      <PermissionCheckerV2 requiredPermission='ops.eb_view_participant_list'>
                        <Button
                          type='ghost'
                          onClick={() => downloadListRequest({ company_id: props.companyId })}
                          loading={!!DOWNLOAD_PARTICIPANTS_LOADER}
                        >
                          <Icon type='cloud-download' /> Download
                        </Button>
                      </PermissionCheckerV2>
                    </Col>
                  </Row>
                </Col>
                <Col>
                  <PermissionCheckerV2
                    requiredPermission='ops.eb_view_participant_list'
                  >
                    <Button type='primary' onClick={openEmployeeListPage} icon='team'>Manage Participants</Button>
                  </PermissionCheckerV2>
                </Col>
                <Col>
                  <PermissionCheckerV2
                    requiredPermission='ops.eb_view_participant_list'
                  >
                    <Button type='link' onClick={openParticipantsList}>Participant List <Icon type='caret-right' /></Button>
                  </PermissionCheckerV2>
                </Col>
              </Row>
            </Col>
          </RowWithMargin>
          <Spin spinning={PARTICIPANTS_INFO_LOADER}>
            {(PARTICIPANTS_INFO_ERROR) && <Alert type='error' message={participantsInfoStatus} banner />}
            {(DOWNLOAD_PARTICIPANTS_ERROR) && <Alert type='error' message={downloadParticipantsStatus} banner />}
            {(participantsInfoData && participantsInfoData.data) && participantsInfoData.data.payment_status && !PARTICIPANTS_INFO_ERROR
              ? (
                <>
                  <RowWithMargin>
                    <Col span={8}>
                      <Row>
                        <Col span={12}>
                          <Text strong style={{ color: 'rgb(50,215,75)' }}>
                            <Tag color='#87d068'>Paid  {participantsInfoData.data.payment_status.PAID}</Tag>
                          </Text>
                        </Col>
                      </Row>
                    </Col>
                    <Col span={8}>
                      <Row>
                        <Col span={12}>
                          <Text strong style={{ color: 'rgb(255,69,58)' }}>
                            <Tag color='#f50'>Unpaid  {participantsInfoData.data.payment_status.UNPAID}</Tag>
                          </Text>
                        </Col>
                      </Row>
                    </Col>
                    <Col span={8}>
                      <Row>
                        <Col span={12}>
                          <Text strong style={{ color: 'rgb(255,169,0)' }}>
                            <Tag color='#FFA500'>Pending  {participantsInfoData.data.payment_status.PENDING}</Tag>
                          </Text>
                        </Col>
                      </Row>
                    </Col>
                  </RowWithMargin>
                  <Row>
                    <Col span={8}>
                      <RowWithMargin marginSize='small'>
                        <Col span={12}><Text strong>Man</Text></Col>
                        <Col span={12}>{participantsInfoData.data.man['<=55'] + participantsInfoData.data.man['56-60'] + participantsInfoData.data.man['61-64'] + participantsInfoData.data.man['65-75']}</Col>
                      </RowWithMargin>
                      <Row>
                        <Col span={12}><Text strong>{'<=55 years old'}</Text></Col>
                        <Col span={12}><Text strong>{participantsInfoData.data.man['<=55']}</Text></Col>
                      </Row>
                      <Row>
                        <Col span={12}><Text strong>55-60 years old</Text></Col>
                        <Col span={12}><Text strong>{participantsInfoData.data.man['56-60']}</Text></Col>
                      </Row>
                      <Row>
                        <Col span={12}><Text strong>61-64 years old</Text></Col>
                        <Col span={12}><Text strong>{participantsInfoData.data.man['61-64']}</Text></Col>
                      </Row>
                      <Row>
                        <Col span={12}><Text strong>65-75 years old</Text></Col>
                        <Col span={12}><Text strong>{participantsInfoData.data.man['65-75']}</Text></Col>
                      </Row>
                    </Col>
                    <Col span={8}>
                      <RowWithMargin marginSize='small'>
                        <Col span={12}><Text strong>Woman</Text></Col>
                        <Col span={12}>{participantsInfoData.data.woman['<=55'] + participantsInfoData.data.woman['56-60'] + participantsInfoData.data.woman['61-64'] + participantsInfoData.data.woman['65-75']}</Col>
                      </RowWithMargin>
                      <Row>
                        <Col span={12}><Text strong>{'<=55 years old'}</Text></Col>
                        <Col span={12}><Text strong>{participantsInfoData.data.woman['<=55']}</Text></Col>
                      </Row>
                      <Row>
                        <Col span={12}><Text strong>55-60 years old</Text></Col>
                        <Col span={12}><Text strong>{participantsInfoData.data.woman['56-60']}</Text></Col>
                      </Row>
                      <Row>
                        <Col span={12}><Text strong>61-64 years old</Text></Col>
                        <Col span={12}><Text strong>{participantsInfoData.data.woman['61-64']}</Text></Col>
                      </Row>
                      <Row>
                        <Col span={12}><Text strong>65-75 years old</Text></Col>
                        <Col span={12}><Text strong>{participantsInfoData.data.woman['65-75']}</Text></Col>
                      </Row>
                    </Col>
                    <Col span={8}>
                      <RowWithMargin marginSize='small'>
                        <Col span={12}><Text strong>Kid</Text></Col>
                        <Col span={12}>{participantsInfoData.data.kid}</Col>
                      </RowWithMargin>
                    </Col>
                  </Row>
                </>
                )
              : <Empty />}

          </Spin>
        </LayoutContent>
      </LayoutContentWrapper>
    </>
  )
}

export default ParticipantInfo
