import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {

  COMPANY_DETAIL: 'COMPANY_DETAIL',
  COMPANY_DETAIL_REQUEST: 'COMPANY_DETAIL_REQUEST',
  PARTICIPANTS_INFO: 'PARTICIPANTS_INFO',
  PARTICIPANTS_INFO_REQUEST: 'PARTICIPANTS_INFO_REQUEST',
  DOWNLOAD_EMPLOYEES_REQUEST: 'DOWNLOAD_EMPLOYEES_REQUEST',
  DOWNLOAD_EMPLOYEES: 'DOWNLOAD_EMPLOYEES',
  EMPLOYEE_DATA_UPLOAD: 'EMPLOYEE_DATA_UPLOAD',
  EMPLOYEE_DATA_UPLOAD_REQUEST: 'EMPLOYEE_DATA_UPLOAD_REQUEST',
  COMPANY_PACKAGE_REQUEST: 'COMPANY_PACKAGE_REQUEST',
  COMPANY_PACKAGE: 'COMPANY_PACKAGE',
  COMPANY_PAYMENTS_REQUEST: 'COMPANY_PAYMENTS_REQUEST',
  COMPANY_PAYMENTS: 'COMPANY_PAYMENTS',
  FILE_DOWNLOAD_REQUEST: 'FILE_DOWNLOAD_REQUEST',
  FILE_DOWNLOAD: 'FILE_DOWNLOAD',
  FILE_UPLOAD_REQUEST: 'FILE_UPLOAD_REQUEST',
  FILE_UPLOAD: 'FILE_UPLOAD',
  QUOTATION_PURPOSE_REQUEST: 'QUOTATION_PURPOSE_REQUEST',
  QUOTATION_PURPOSE: 'QUOTATION_PURPOSE',
  ACCEPT_PAYMENT_REQUEST: 'ACCEPT_PAYMENT_REQUEST',
  ACCEPT_PAYMENT: 'ACCEPT_PAYMENT',
  CANCEL_PAYMENT_REQUEST: 'CANCEL_PAYMENT_REQUEST',
  CANCEL_PAYMENT: 'CANCEL_PAYMENT',

  getCompanyDetails: (payload) => ({
    type: actions.COMPANY_DETAIL_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.companyDetails
    }
  }),
  getParticipantsInfo: (payload) => (
    {
      type: actions.PARTICIPANTS_INFO_REQUEST,
      payload: {
        ...payload,
        method: 'get',
        url: ebUrls.participantsInfo
      }
    }
  ),
  downloadEmployees: payload => ({
    type: actions.DOWNLOAD_EMPLOYEES_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.downloadEmployeeList
    }
  }),
  employeeDataUpload: (payload) => (
    {
      type: actions.EMPLOYEE_DATA_UPLOAD_REQUEST,
      payload: {
        ...payload,
        method: 'uploadFile',
        url: ebUrls.fileUpload,
        signedUrl: ebUrls.generateSignedUrl
      }
    }
  ),
  getCompanyPayments: (payload) => (
    {
      type: actions.COMPANY_PAYMENTS_REQUEST,
      payload: {
        ...payload,
        method: 'get',
        url: ebUrls.companyPayments
      }
    }
  ),
  fileDownload: (payload) => (
    {
      type: actions.FILE_DOWNLOAD_REQUEST,
      payload: {
        method: 'get',
        url: ebUrls.fileDownload,
        ...payload
      }
    }
  ),
  fileUpload: (payload) => (
    {
      type: actions.FILE_UPLOAD_REQUEST,
      payload: {
        ...payload,
        method: 'uploadFile',
        url: ebUrls.fileUpload,
        signedUrl: ebUrls.generateSignedUrl
      }
    }
  ),
  getQuotationData: (payload) => (
    {
      type: actions.QUOTATION_PURPOSE_REQUEST,
      payload: {
        ...payload,
        method: 'get',
        url: ebUrls.quotationDetails
      }
    }
  ),
  acceptPayment: (payload) => (
    {
      type: actions.ACCEPT_PAYMENT_REQUEST,
      payload: {
        ...payload,
        method: 'post',
        url: ebUrls.acceptPayment
      }
    }
  ),
  cancelPayment: (payload) => (
    {
      type: actions.CANCEL_PAYMENT_REQUEST,
      payload: {
        ...payload,
        method: 'post',
        url: ebUrls.cancelPayment
      }
    }
  ),
  getCompanyPackages: (payload) => (
    {
      type: actions.COMPANY_PACKAGE_REQUEST,
      payload: {
        ...payload,
        method: 'get',
        url: ebUrls.companyPackages
      }
    }
  )
}

export default actions
