/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect } from 'react'
import {
  Modal,
  Col,
  Alert,
  Spin
} from 'antd'
import { useUpdatePayment } from '../../../../../../state/Company/hooks/useCompany'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { formatIntlCurrency } from '../../../../../../../../../helpers/utility'
import { useResetState } from '../../../../../../state/hooks'
import { RowWithMargin } from '../../../../../../CommonComponents'

const CancelPayment = ({ ...props }) => {
  const [, , cancelPaymentRequest] = useUpdatePayment()
  const [{ CANCEL_PAYMENT_ERROR, cancelPaymentStatus }] = useErrorContextValue()
  const [{ CANCEL_PAYMENT_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()
  const { resetState } = useResetState()

  const cancelPayment = () => {
    cancelPaymentRequest({ body: { payment_id: props.data.id } })
  }
  useEffect(() => {
    if (cancelPaymentStatus === 'success') {
      resetState(['cancelPaymentStatus', 'companyPaymentsData', 'participantsInfoStatus'])
      resetError(['COMPANY_PAYMENTS_ERROR', 'companyPaymentsStatus', 'cancelPaymentStatus'])
      props.onCancel()
    }
  }, [cancelPaymentStatus])

  return (
    <Modal
      visible
      title='Cancel Payment'
      onOk={cancelPayment}
      onCancel={props.onCancel}
      okText='Yes'
      cancelText='No'
    >
      <Spin spinning={!!CANCEL_PAYMENT_LOADER}>
        {CANCEL_PAYMENT_ERROR && <Alert type='error' message={cancelPaymentStatus} banner />}
        <RowWithMargin>
          <Col span={12}>ID</Col>
          <Col span={12}>{props.data ? props.data.id : '-'}</Col>
        </RowWithMargin>
        <RowWithMargin>
          <Col span={12}>Package ID</Col>
          <Col span={12}>{props.data ? props.data.packageID : '-'}</Col>
        </RowWithMargin>
        <RowWithMargin>
          <Col span={12}>Amount</Col>
          <Col span={12}>{props.data ? formatIntlCurrency(props.data.amount) : '-'}</Col>
        </RowWithMargin>
      </Spin>
    </Modal>
  )
}

export default CancelPayment
