import React, { useEffect } from 'react'
import { Typography, Spin, Empty, Row, Col, Alert, Button, Icon } from 'antd'
import { format } from 'date-fns'
import LayoutContent from '../../../../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../../../../components/utility/layoutWrapper'
// import { RowWithMargin } from '../../CommonComponents/index'
import { useCompanyDetails } from '../../../../state/Company/hooks/useCompany'
// import { useErrorContextValue } from '../../../../../globalContextProvider/ErrorContext'
// import { useLoaderContextValue } from '../../../../../globalContextProvider/LoaderContext'
// import { ColTextAlignRight } from '../../CommonComponents/index.style'
import PermissionCheckerV2 from '../../../../../../../components/permissionCheckerV2'
import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { RowWithMargin } from '../../../../CommonComponents'
import { ColTextAlignRight } from '../../../../CommonComponents/index.style'

const { Title, Text } = Typography

const CompanyDetail = ({ history, companyId, ...props }) => {
  const [{ companyDetailData }, request] = useCompanyDetails()
  const [{ COMPANY_DETAIL_LOADER, UPDATE_COMPANY_LOADER }] = useLoaderContextValue()
  const [{ COMPANY_DETAIL_ERROR, companyDetailStatus }] = useErrorContextValue()

  useEffect(() => {
    const query = {
      company_id: companyId
    }
    request({ query })
  }, [request, companyId])

  return (
    <LayoutContentWrapper>
      <LayoutContent>
        <Spin spinning={!!COMPANY_DETAIL_LOADER || !!UPDATE_COMPANY_LOADER}>
          <Row>
            <Col span={12}>
              <Title level={4}>
                Company Info
              </Title>
            </Col>
            <ColTextAlignRight offset={8} span={4}>
              <PermissionCheckerV2 requiredPermission='ops.eb_view_company_uploaded_file_list'>
                <Button
                  type='link'
                  onClick={() => history.push(`/employee-benefits/company-list/${companyId}/file-uploads`)}
                >
                  File uploads
                  <Icon type='caret-right' />
                </Button>
              </PermissionCheckerV2>
            </ColTextAlignRight>
          </Row>
          {COMPANY_DETAIL_ERROR && <Alert type='error' message={companyDetailStatus} banner />}
          {(companyDetailData && companyDetailData.data && !COMPANY_DETAIL_ERROR)
            ? (
              <>
                <RowWithMargin>
                  <Col span={8}>
                    <Row>
                      <Col span={12}><Text strong>Name</Text></Col>
                      <Col span={12}>{companyDetailData.data.name}</Col>
                    </Row>
                  </Col>
                  <Col span={8}>
                    <Row>
                      <Col span={12}><Text strong>Contact Name</Text></Col>
                      <Col span={12}>{companyDetailData.data.contact_name}</Col>
                    </Row>
                  </Col>
                  <Col span={8}>
                    <Row>
                      <Col span={12}><Text strong>Industry</Text></Col>
                      <Col span={12}>{companyDetailData.data.industry}</Col>
                    </Row>
                  </Col>
                </RowWithMargin>
                <RowWithMargin>
                  <Col span={8}>
                    <Row>
                      <Col span={12}><Text strong>Line of Business</Text></Col>
                      <Col span={12}>{companyDetailData.data.line_of_business}</Col>
                    </Row>
                  </Col>
                  <Col span={8}>
                    <Row>
                      <Col span={12}><Text strong>Created at</Text></Col>
                      <Col span={12}>{format(new Date(companyDetailData.data.contact_created_at), 'DD MMMM YYYY')}</Col>
                    </Row>
                  </Col>
                  <Col span={8}>
                    <Row>
                      <Col span={12}><Text strong>Employee Size</Text></Col>
                      <Col span={12}>{companyDetailData.data.size}</Col>
                    </Row>
                  </Col>
                </RowWithMargin>
                <RowWithMargin>
                  <Col span={8}>
                    <Row>
                      <Col span={12}><Text strong>Contact Phone</Text></Col>
                      <Col span={12}>{companyDetailData.data.contact_phone}</Col>
                    </Row>
                  </Col>
                  <Col span={8}>
                    <Row>
                      <Col span={12}><Text strong>Contact email</Text></Col>
                      <Col span={12}>{companyDetailData.data.contact_email}</Col>
                    </Row>
                  </Col>
                </RowWithMargin>
              </>)
            : <Empty />}
        </Spin>
      </LayoutContent>
    </LayoutContentWrapper>
  )
}

export default CompanyDetail
