/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react'
import { Button, Statistic, Typography, Row, Col, Upload, Spin, Empty, Icon, Alert, message } from 'antd'
import { format } from 'date-fns'
import LayoutContent from '../../../../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../../../../components/utility/layoutWrapper'
import { useQuotationDetails, useFileUpload, useFileDownLoad } from '../../../../state/Company/hooks/useCompany'
import ebUrls from '../../../../../../../request/urls/employeeBenefit'
import PermissionCheckerV2 from '../../../../../../../components/permissionCheckerV2'
import { StyledRow } from './index.style'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { RowWithMargin, Ul, Chips } from '../../../../CommonComponents'
import lodash, { isEmpty } from 'lodash'

const { Title, Text } = Typography

const QuotationPurposeData = (props) => {
  const [{ quotationPurposeData }, request] = useQuotationDetails()
  const [{ QUOTATION_PURPOSE_LOADER }] = useLoaderContextValue()
  const [{ QUOTATION_PURPOSE_ERROR, quotationPurposeStatus, FILE_UPLOAD_ERROR, fileDownloadStatus, fileUploadStatus }] = useErrorContextValue()
  const [{ fileUploadData }, uploadRequest] = useFileUpload()
  const [{ fileDownloadData }, downloadRequest] = useFileDownLoad()
  const [fileUploadState, setFileUploadState] = useState({ spak: '', tdp: '', ktp: '', files: '', npwp: '', prev_policy: '' })
  const { resetError } = useResetError()

  useEffect(() => {
    if (fileUploadStatus === 'success' && !isEmpty(fileUploadData)) {
      const query = {
        company_id: props.companyId
      }
      request({ query })

      setFileUploadState(state => ({ ...state, [fileUploadData.document_type]: 'done' }))
    }
  }, [fileUploadData, fileUploadStatus])

  useEffect(() => {
    if (FILE_UPLOAD_ERROR) {
      // TODO: handle error in file upload api
      setFileUploadState(
        { spak: 'done', tdp: 'done', ktp: 'done', files: 'done', npwp: 'done', prev_policy: 'done' }
      )
      message.error('Upload failed')
      resetError(['FILE_UPLOAD_ERROR'])
    }
  }, [FILE_UPLOAD_ERROR])

  const customRequest = ({ file }, documentType) => {
    const { size } = file
    const isLt10KB = size / 1024 / 1024 < 0.01
    const isGt20MB = size / 1024 / 1024 > 20
    if (isLt10KB) {
      message.error('File is to small, min 10kb')
      setFileUploadState(state => ({ ...state, [documentType]: 'done' }))
      return
    }
    if (isGt20MB) {
      message.error('File is to big, max 20mb')
      setFileUploadState(state => ({ ...state, [documentType]: 'done' }))
      return
    }
    if (!isLt10KB && !isGt20MB) {
      const formData = new FormData()
      formData.append('file', file)
      formData.append('document_type', documentType)
      formData.append('company_id', props.companyId)
      setFileUploadState(state => ({ ...state, [documentType]: '' }))
      uploadRequest({
        params: {},
        // body: {file, documentType, companyId: props.companyId }
        body: { file, documentType, companyId: props.companyId },
        signedUrlBody: { file_name: file.name, identifier: 'company', content_type: file.type },
        uploadBody: { document_type: documentType, company_id: props.companyId },
        customReturnData: { document_type: documentType },
        uploadUrl: ebUrls.fileUpload
      })
    } else {
      message.error('Incorrect file type, please upload .jpeg/.jpg/.png')
    }
  }

  const downloadDoc = (identifier) => {
    downloadRequest({
      query: {
        company_id: props.companyId,
        document_type: identifier
      }
    })
  }
  useEffect(() => {
    if (fileDownloadStatus === 'success' && !lodash.isEmpty(fileDownloadData)) {
      window.open(fileDownloadData.signed_url, '_blank')
    }
    return () => {
      // reset states here
    }
  }, [fileDownloadData, fileDownloadStatus])

  useEffect(() => {
    const query = {
      company_id: props.companyId
    }
    request({ query })
  }, [])
  return (
    <LayoutContentWrapper>
      <LayoutContent>
        <Title level={4}>
          Quotation Purpose Data
        </Title>
        <Spin spinning={QUOTATION_PURPOSE_LOADER}>
          {QUOTATION_PURPOSE_ERROR && <Alert type='error' message={quotationPurposeStatus} banner />}
          {
            (quotationPurposeData && quotationPurposeData.data && !QUOTATION_PURPOSE_ERROR)
              ? (
                <>
                  <RowWithMargin>
                    <Col span={8}>
                      <Row>
                        <Col span={12}>
                          <Text strong>
                            Budget
                          </Text>
                        </Col>
                        <Col span={12}>
                          IDR
                          <Statistic value={quotationPurposeData.data.expected_total_budget || 0} precision={0} />
                        </Col>
                      </Row>
                    </Col>
                    <Col span={8}>
                      <Row>
                        <Col span={24}>
                          <Text strong>
                            Preferred Insurance Provider
                            <StyledRow>
                              {!quotationPurposeData.data.desired_insurance.length ? '-' : null}
                              {quotationPurposeData.data.desired_insurance.map((d, index) => (<Chips key={index}>{d}</Chips>))}
                            </StyledRow>
                          </Text>
                        </Col>
                      </Row>
                    </Col>
                    <Col span={8}>
                      <Row>
                        <Col span={12}>
                          <Text strong>Benefit Choosen</Text>
                          <Ul>
                            {quotationPurposeData.data.coverage_type.map((d, index) => (<li key={index}>{d}</li>))}
                          </Ul>
                        </Col>
                      </Row>
                    </Col>
                  </RowWithMargin>
                  <RowWithMargin>
                    <Col span={8}>
                      <Row>
                        <Col span={12}>
                          <Text strong>
                            Existing Policy
                          </Text>
                        </Col>
                        <Col span={12}>
                          <PermissionCheckerV2
                            requiredPermission='ops.eb_upload_company_documents'
                          >
                            <Upload
                              customRequest={(file) => { customRequest(file, 'prev_policy') }}
                              {...(fileUploadState.prev_policy === 'done' ? { fileList: [] } : null)}
                            >
                              <Button type='secondary'><Icon type='cloud-upload' />{quotationPurposeData.data.documents.prev_policy !== '' ? 'Re Upload' : 'Upload'}</Button>
                            </Upload>
                          </PermissionCheckerV2>
                        </Col>
                        <Col>
                          {
                            quotationPurposeData.data.documents.prev_policy !== '' && (
                              <PermissionCheckerV2
                                requiredPermission='ops.eb_view_company_documents'
                              >
                                <Col span={12}>
                                  <span className='anchor' onClick={() => downloadDoc('prev_policy')}>
                                    <Icon type='export' />View
                                  </span>
                                </Col>
                              </PermissionCheckerV2>
                            )
                          }
                        </Col>
                      </Row>
                    </Col>
                    <Col span={8}>
                      <Row>
                        <Col span={24}>
                          <Text strong>
                            Blacklisted Insurance Provider
                            <StyledRow>
                              {!quotationPurposeData.data.unwanted_insurance.length ? '-' : null}
                              {quotationPurposeData.data.unwanted_insurance.map((d, index) => (<Chips key={index} bgColor='rgb(142,142,147)'>{d}</Chips>))}
                            </StyledRow>
                          </Text>
                        </Col>
                      </Row>
                    </Col>
                  </RowWithMargin>
                  <RowWithMargin>
                    <Col span={8}>
                      <Row>
                        <Col span={12}>
                          <Text strong>
                            Preferred Coverage Start Date
                          </Text>
                        </Col>
                        <Col span={12}>{format(new Date(quotationPurposeData.data.expected_protection_start_date), 'DD MMMM YYYY')}</Col>
                      </Row>
                    </Col>
                    <Col span={8}>
                      <Row>
                        <Col span={12}>
                          <Text strong>
                            SPAK Perusahaan
                          </Text>
                        </Col>
                        <Col span={12}>
                          <PermissionCheckerV2
                            requiredPermission='ops.eb_upload_company_documents'
                          >
                            <Upload
                              customRequest={(file) => { customRequest(file, 'spak') }}
                              {...(fileUploadState.spak === 'done' ? { fileList: [] } : null)}
                              multiple={false}
                            >
                              <Button type='secondary'><Icon type='cloud-upload' />{quotationPurposeData.data.documents.spak !== '' ? 'Re Upload' : 'Upload'}</Button>
                            </Upload>
                          </PermissionCheckerV2>
                        </Col>
                        <Col>
                          <PermissionCheckerV2
                            requiredPermission='ops.eb_view_company_documents'
                          >
                            {quotationPurposeData.data.documents.spak !== '' && <Col span={12}><span className='anchor' onClick={() => downloadDoc('spak')}><Icon type='export' />View</span></Col>}
                          </PermissionCheckerV2>
                        </Col>
                      </Row>
                    </Col>
                  </RowWithMargin>
                  <RowWithMargin>
                    <Col span={8}>
                      <Row>
                        <Col span={12}>
                          <Text strong>
                            Preferred Payment
                          </Text>
                        </Col>
                        <Col span={12}>{quotationPurposeData.data.preferred_payment_method}</Col>
                      </Row>
                    </Col>
                    <Col span={8}>
                      <Row>
                        <Col span={12}>
                          <Text strong>
                            TDP
                          </Text>
                        </Col>
                        <Col span={12}>
                          <PermissionCheckerV2
                            requiredPermission='ops.eb_upload_company_documents'
                          >
                            <Upload
                              customRequest={(file) => { customRequest(file, 'tdp') }}
                              {...(fileUploadState.tdp === 'done' ? { fileList: [] } : null)}
                            >
                              <Button type='secondary'><Icon type='cloud-upload' />{quotationPurposeData.data.documents.tdp !== '' ? 'Re Upload' : 'Upload'}</Button>
                            </Upload>
                          </PermissionCheckerV2>
                        </Col>
                        <Col>
                          <PermissionCheckerV2
                            requiredPermission='ops.eb_view_company_documents'
                          >
                            {quotationPurposeData.data.documents.tdp !== '' && <Col span={12}><span className='anchor' onClick={() => downloadDoc('tdp')}><Icon type='export' />View</span></Col>}
                          </PermissionCheckerV2>
                        </Col>
                      </Row>
                    </Col>
                  </RowWithMargin>
                  <RowWithMargin>
                    <Row>
                      <Col span={8}>
                        <Row>
                          <Col span={12}>
                            <Text strong>
                              KTP Direksi
                            </Text>
                          </Col>
                          <Col span={12}>
                            <PermissionCheckerV2
                              requiredPermission='ops.eb_upload_company_documents'
                            >
                              <Upload
                                customRequest={(file) => { customRequest(file, 'ktp') }}
                                {...(fileUploadState.ktp === 'done' ? { fileList: [] } : null)}
                              >
                                <Button type='secondary'><Icon type='cloud-upload' />{quotationPurposeData.data.documents.ktp !== '' ? 'Re Upload' : 'Upload'}</Button>
                              </Upload>
                            </PermissionCheckerV2>
                          </Col>
                          <Col>
                            <PermissionCheckerV2
                              requiredPermission='ops.eb_view_company_documents'
                            >
                              {quotationPurposeData.data.documents.ktp !== '' && <Col span={12}><span className='anchor' onClick={() => downloadDoc('ktp')}><Icon type='export' />View</span></Col>}
                            </PermissionCheckerV2>
                          </Col>
                        </Row>
                      </Col>
                      <Col span={8}>
                        <Row>
                          <Col span={12}>
                            <Text strong>
                              NPWP Perusahaan
                            </Text>
                          </Col>
                          <Col span={12}>
                            <PermissionCheckerV2
                              requiredPermission='ops.eb_upload_company_documents'
                            >
                              <Upload
                                customRequest={(file) => { customRequest(file, 'npwp') }}
                                {...(fileUploadState.npwp === 'done' ? { fileList: [] } : null)}
                              >
                                <Button type='secondary'><Icon type='cloud-upload' />{quotationPurposeData.data.documents.npwp !== '' ? 'Re Upload' : 'Upload'}</Button>
                              </Upload>
                            </PermissionCheckerV2>
                          </Col>
                          <Col>
                            <PermissionCheckerV2
                              requiredPermission='ops.eb_view_company_documents'
                            >
                              {quotationPurposeData.data.documents.npwp !== '' && <Col span={12}><span className='anchor' onClick={() => downloadDoc('npwp')}><Icon type='export' />View</span></Col>}
                            </PermissionCheckerV2>
                          </Col>
                        </Row>
                      </Col>
                    </Row>
                  </RowWithMargin>
                  <RowWithMargin>
                    <Row>
                      <Col span={8}>
                        <Row>
                          <Col span={12}>
                            <Text strong>
                              Akte Perusahaan
                            </Text>
                          </Col>
                          <Col span={12}>
                            <PermissionCheckerV2
                              requiredPermission='ops.eb_upload_company_documents'
                            >
                              <Upload
                                customRequest={(file) => { customRequest(file, 'files') }}
                                {...(fileUploadState.files === 'done' ? { fileList: [] } : null)}
                              >
                                <Button type='secondary'><Icon type='cloud-upload' />{quotationPurposeData.data.documents.files !== '' ? 'Re Upload' : 'Upload'}</Button>
                              </Upload>
                            </PermissionCheckerV2>
                          </Col>
                          <Col>
                            <PermissionCheckerV2
                              requiredPermission='ops.eb_view_company_documents'
                            >
                              {quotationPurposeData.data.documents.files !== '' && <Col span={12}><span className='anchor' onClick={() => downloadDoc('files')}><Icon type='export' />View</span></Col>}
                            </PermissionCheckerV2>
                          </Col>
                        </Row>
                      </Col>
                    </Row>
                  </RowWithMargin>
                </>
                )
              : <Empty />
}
        </Spin>
      </LayoutContent>
    </LayoutContentWrapper>
  )
}

export default QuotationPurposeData
