import React, { useEffect } from 'react'
import ParticipantInfo from './ParticipantInfo'
import QuotationPurposeData from './QuotationPurposeData'
import Package from './Package'
import PaymentHistory from './PaymentHistory'
import CompanyDetail from './Companydetail'
// import { useError } from '../../../../state/error/hooks/useError'
import { Button, Icon } from 'antd'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { useResetState } from '../../../state/hooks'
import { useResetError } from '@pasarpolis/common-react-hooks'

const CompanyDetails = (props) => {
  const { resetState } = useResetState()
  const { resetError } = useResetError()
  const goBack = () => {
    props.history.push('/employee-benefits/company-list/')
  }

  useEffect(() => {
    return () => {
      resetState(['acceptPaymentStatus',
        'downloadParticipantStatus',
        'fileUploadStatus',
        'fileDownloadStatus',
        'companyDetailData',
        'downloadParticipantData',
        'quotationPurposeData',
        'companyPackageData',
        'companyPaymentsData'
      ])
      resetError([
        'companyDetailStatus',
        'participantsInfoStatus',
        'quotationPurposeStatus',
        'companyPackageStatus',
        'companyPaymentsStatus',
        'COMPANY_DETAIL_ERROR',
        'PARTICIPANTS_INFO_ERROR',
        'DOWNLOAD_PARTICIPANT_ERROR',
        'QUOTATION_PURPOSE_ERROR',
        'COMPANY_PACKAGE_ERROR',
        'COMPANY_PAYMENTS_ERROR'
      ])
    }
  }, [resetState, resetError])
  return (
    <>
      <div className='back-button-layout'>
        <Button type='default' onClick={goBack}><Icon type='caret-left' />Back</Button>
      </div>
      <CompanyDetail companyId={props.match.params.id} history={props.history} />
      <PermissionCheckerV2 requiredPermission='ops.eb_view_aggregated_participant_info'>
        <ParticipantInfo companyId={props.match.params.id} history={props.history} />
      </PermissionCheckerV2>
      <PermissionCheckerV2 requiredPermission='ops.eb_view_quotation_data'>
        <QuotationPurposeData companyId={props.match.params.id} />
      </PermissionCheckerV2>
      <PermissionCheckerV2 requiredPermission='ops.eb_view_package_list'>
        <Package companyId={props.match.params.id} history={props.history} />
      </PermissionCheckerV2>
      <PermissionCheckerV2 requiredPermission='ops.eb_view_payment_history'>
        <PaymentHistory companyId={props.match.params.id} />
      </PermissionCheckerV2>
    </>
  )
}

export default CompanyDetails
