import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useEBContextValue } from '../../../context/index'
import actions from '../actions'
import useFileUploadServiceRequest from '../../useFileUploadServiceRequest'
import { useCallback } from 'react'

export const useCompanyDetails = () => {
  const [{ companyDetailData, companyDetailStatus }, dispatch] = useEBContextValue()
  //  follow this
  const [callApi] = useServiceRequest(dispatch)
  const request = useCallback((payload = {}) => {
    callApi(actions.getCompanyDetails(payload))
  }, [callApi])
  return [{ companyDetailData, companyDetailStatus }, request]
}

export const useParticipantInfo = () => {
  const [{
    participantsInfoData,
    participantsInfoStatus
  }, dispatch] = useEBContextValue()
  //  follow this
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(actions.getParticipantsInfo(payload))
  }
  return [{
    participantsInfoData,
    participantsInfoStatus
  }, request]
}

export const useDownloadEmployees = () => {
  const [{ downloadEmployeesData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const downloadEmployeesRequest = useCallback((payload) => {
    callApi(actions.downloadEmployees({ query: payload }))
  }, [callApi])
  return { downloadEmployeesData, downloadEmployeesRequest }
}

