export const useUpdatePayment = () => {
  const [{ acceptPaymentData, acceptPaymentStatus, cancelPaymentData, cancelPaymentStatus }, dispatch] = useEBContextValue()
  //  follow this
  const [callApi] = useServiceRequest(dispatch)
  const acceptPaymentRequest = async (payload = {}) => {
    await callApi(actions.acceptPayment(payload))
  }
  const cancelPaymentRequest = async (payload = {}) => {
    await callApi(actions.cancelPayment(payload))
  }
  return [{ acceptPaymentData, acceptPaymentStatus, cancelPaymentData, cancelPaymentStatus }, acceptPaymentRequest, cancelPaymentRequest]
}
