import { ApiContextProvider } from '@pasarpolis/common-react-hooks'
import React from 'react'
import { EBContextProvider } from '../../context'
import reducer from '../../state/Company/reducers'
import CompanyContainer from './containers'

function Users (props) {
  return (
    <EBContextProvider reducer={reducer} pageName='Company'>
      <ApiContextProvider>
        <CompanyContainer {...props} />
      </ApiContextProvider>
    </EBContextProvider>
  )
}

export default Users
